-- Lote 2/4: 25 questões médias por obra (50 no total).
WITH incoming AS (
  SELECT * FROM jsonb_to_recordset($questions$[{"book":"livro_espiritos","statement":"A resposta à questão 23 distingue o Espírito da matéria ao definir o Espírito como quê?","option_a":"O princípio inteligente do Universo.","option_b":"Uma forma sutil de matéria comum.","option_c":"A energia produzida pelo cérebro.","option_d":"O conjunto das leis físicas.","option_e":"Uma propriedade exclusiva dos seres humanos encarnados.","correct_option":"A","explanation":"A obra define o Espírito como princípio inteligente do Universo, distinguindo-o da matéria.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. II, questão 23.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é a relação entre o princípio inteligente e os seres vivos, segundo o capítulo sobre o princípio vital?","option_a":"O princípio inteligente é idêntico ao calor corporal.","option_b":"A vida orgânica, por si só, explica toda consciência espiritual.","option_c":"Todo ser orgânico possui a mesma inteligência humana.","option_d":"A matéria viva não depende de organização.","option_e":"O princípio vital e o princípio inteligente são conceitos distintos na exposição da obra.","correct_option":"E","explanation":"A obra diferencia o princípio vital, ligado à vida orgânica, do princípio inteligente, relacionado ao Espírito.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. IV, questões 60–71.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Por que, segundo a questão 132, os Espíritos passam pela vida corporal?","option_a":"Para sofrer sem finalidade.","option_b":"Para cumprir uma etapa de progresso e assumir sua parte na obra da criação.","option_c":"Para adquirir apenas conhecimento científico.","option_d":"Para abandonar definitivamente o mundo espiritual.","option_e":"Para receber recompensas materiais.","correct_option":"B","explanation":"A encarnação permite aos Espíritos alcançar a perfeição e participar da obra divina, conforme suas capacidades.","reference":"O Livro dos Espíritos, Livro Segundo, cap. II, questão 132.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Como a obra relaciona a escolha das provas à liberdade do Espírito?","option_a":"O Espírito escolhe necessariamente todos os detalhes de sua vida futura.","option_b":"A escolha é feita pelos familiares encarnados.","option_c":"Nenhum Espírito participa da preparação de sua existência.","option_d":"A escolha ocorre dentro de limites ligados ao estado evolutivo e às necessidades de progresso.","option_e":"A escolha elimina toda consequência de atos anteriores.","correct_option":"D","explanation":"A obra descreve uma participação do Espírito na escolha de provas, condicionada por sua condição e pelo objetivo de progresso.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questões 258–273.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é a finalidade do esquecimento das existências anteriores, conforme a questão 392?","option_a":"Evitar que lembranças explícitas prejudiquem a nova experiência e as relações presentes.","option_b":"Apagar a responsabilidade por todos os atos passados.","option_c":"Impedir o reconhecimento de qualquer aprendizado.","option_d":"Provar que não há continuidade espiritual.","option_e":"Eliminar a liberdade do encarnado.","correct_option":"A","explanation":"O esquecimento permite que o Espírito enfrente uma nova existência sem ser constantemente condicionado pelas recordações do passado.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VII, questão 392.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Na escala espírita, o que caracteriza essencialmente os Espíritos puros?","option_a":"A capacidade de dominar fenômenos naturais.","option_b":"A ausência de individualidade.","option_c":"A perfeição moral e a ausência de influência da matéria.","option_d":"A necessidade de novas encarnações expiatórias.","option_e":"A posse de conhecimentos limitados à Terra.","correct_option":"C","explanation":"A escala espírita descreve os Espíritos puros como aqueles que alcançaram a perfeição, sem precisar passar por novas provas corporais.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questões 112–113.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é a distinção apresentada entre erraticidade e encarnação?","option_a":"Erraticidade é uma punição; encarnação é sempre recompensa.","option_b":"Erraticidade é o estado do Espírito entre existências corporais; encarnação é sua união temporária a um corpo.","option_c":"Erraticidade ocorre apenas antes da primeira existência.","option_d":"Encarnação significa perder a individualidade.","option_e":"São expressões equivalentes.","correct_option":"B","explanation":"A obra usa erraticidade para designar o intervalo no mundo espiritual entre existências corporais.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VI, questão 224.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Por que a pluralidade dos mundos habitados se harmoniza com a ideia de progresso?","option_a":"Porque todos os mundos têm exatamente o mesmo grau moral.","option_b":"Porque somente a Terra permite evolução.","option_c":"Porque a vida espiritual depende de um único planeta.","option_d":"Porque os Espíritos podem progredir em diferentes mundos, conforme suas condições.","option_e":"Porque os mundos são apenas símbolos literários.","correct_option":"D","explanation":"A obra relaciona a diversidade dos mundos às diferentes etapas e condições de progresso dos Espíritos.","reference":"O Livro dos Espíritos, Livro Primeiro, cap. III, questões 55–58.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é o papel do livre-arbítrio no desenvolvimento moral?","option_a":"Permite ao Espírito escolher e responder por seus atos, dentro das condições de sua existência.","option_b":"Garante que toda escolha seja correta.","option_c":"Elimina a influência das circunstâncias.","option_d":"Torna desnecessário o aprendizado.","option_e":"Impede qualquer influência espiritual.","correct_option":"A","explanation":"O livre-arbítrio está ligado à possibilidade de escolher e à responsabilidade pelas escolhas realizadas.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. X, questões 843–850.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Como a obra diferencia lei natural e legislação humana?","option_a":"A lei natural depende da aprovação dos governos.","option_b":"A legislação humana é sempre perfeita e imutável.","option_c":"A lei natural é divina e universal; as leis humanas são variáveis e devem progredir.","option_d":"As duas são idênticas em origem e duração.","option_e":"A lei natural só vale após ser escrita.","correct_option":"C","explanation":"A lei natural é apresentada como universal, enquanto a legislação humana pode ser aperfeiçoada conforme o progresso social.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. I, questões 614–617.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Por que a adoração exterior, isolada da conduta moral, é insuficiente?","option_a":"Porque toda expressão religiosa é condenada.","option_b":"Porque a forma externa não substitui a sinceridade e a prática do bem.","option_c":"Porque somente a contemplação é válida.","option_d":"Porque a prece não tem utilidade.","option_e":"Porque a moral depende de cerimônias.","correct_option":"B","explanation":"O capítulo sobre a lei de adoração ressalta que o valor moral não está na aparência do culto, mas na intenção e na conduta.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. II, questões 653–656.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"O que a obra considera abuso na destruição?","option_a":"Toda transformação natural da matéria.","option_b":"Qualquer morte de um organismo.","option_c":"A destruição necessária à renovação da natureza.","option_d":"A destruição provocada sem necessidade e além dos limites úteis, por crueldade ou interesse.","option_e":"A decomposição natural dos corpos.","correct_option":"D","explanation":"A obra distingue a destruição necessária, ligada à renovação natural, da destruição abusiva causada por excessos humanos.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VI, questões 728–735.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Como o capítulo sobre a lei de sociedade avalia o isolamento voluntário absoluto?","option_a":"Como ideal obrigatório para todos.","option_b":"Como condição indispensável à caridade.","option_c":"Como contrário à necessidade natural de relações e aprendizado mútuo.","option_d":"Como prova de superioridade moral.","option_e":"Como único caminho para a liberdade.","correct_option":"C","explanation":"A obra afirma a necessidade da vida social e questiona o isolamento que impede a contribuição e o aprendizado recíprocos.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VII, questões 766–772.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é a relação entre progresso intelectual e progresso moral na obra?","option_a":"O progresso intelectual pode anteceder o moral, mas precisa ser acompanhado por ele para o aperfeiçoamento completo.","option_b":"O progresso intelectual torna a moral desnecessária.","option_c":"O progresso moral impede o desenvolvimento intelectual.","option_d":"Ambos são sempre simultâneos e idênticos.","option_e":"Somente a instrução escolar produz progresso moral.","correct_option":"A","explanation":"A obra admite ritmos diferentes entre progresso intelectual e moral, apontando a necessidade de ambos.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VIII, questões 780–785.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Como a obra define a responsabilidade moral de uma ação?","option_a":"Somente pelo resultado material.","option_b":"Exclusivamente pela opinião pública.","option_c":"Pela intenção, pelo conhecimento e pelas condições em que a ação foi praticada.","option_d":"Pelo benefício financeiro obtido.","option_e":"Pela posição social do agente.","correct_option":"C","explanation":"A avaliação moral considera intenção, consciência e circunstâncias, não apenas a aparência externa do ato.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. X, questões 629–646.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"O que a obra indica sobre a influência dos Espíritos nos pensamentos humanos?","option_a":"Que todo pensamento vem necessariamente de um Espírito.","option_b":"Que pode haver influência espiritual, sem eliminar o discernimento e a responsabilidade do encarnado.","option_c":"Que os encarnados não possuem pensamentos próprios.","option_d":"Que a influência ocorre apenas durante o sono.","option_e":"Que a influência espiritual é sempre perceptível.","correct_option":"B","explanation":"O livro aborda a influência espiritual sobre pensamentos e ações, preservando a responsabilidade do indivíduo por suas escolhas.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IX, questões 459–472.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é a função dos Espíritos protetores, conforme o capítulo sobre intervenção espiritual?","option_a":"Determinar todas as decisões do protegido.","option_b":"Garantir que ele nunca enfrente dificuldades.","option_c":"Substituir sua consciência moral.","option_d":"Aconselhar, amparar e inspirar ao bem, respeitando o livre-arbítrio.","option_e":"Impedir qualquer consequência de suas escolhas.","correct_option":"D","explanation":"Os Espíritos protetores oferecem orientação e amparo, mas não anulam a liberdade individual.","reference":"O Livro dos Espíritos, Livro Segundo, cap. IX, questões 489–521.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Por que a obra considera a família importante para o progresso?","option_a":"Porque os vínculos familiares podem oferecer oportunidades de amor, auxílio, reconciliação e aprendizado.","option_b":"Porque todos os laços familiares são necessariamente perfeitos.","option_c":"Porque a família elimina a necessidade de vida social.","option_d":"Porque o parentesco físico garante superioridade moral.","option_e":"Porque os deveres familiares terminam com a infância.","correct_option":"A","explanation":"A obra relaciona os laços familiares a oportunidades de desenvolvimento moral e de fortalecimento dos vínculos espirituais.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VII, questões 773–775.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é o sentido da máxima “fora da caridade não há salvação” na lógica moral da obra?","option_a":"A salvação depende de filiação institucional.","option_b":"A caridade é apenas uma doação financeira.","option_c":"A prática do amor e do bem é essencial, acima de distinções exteriores.","option_d":"A caridade dispensa toda transformação interior.","option_e":"A salvação é privilégio de poucos escolhidos por nascimento.","correct_option":"C","explanation":"A máxima sintetiza a centralidade da caridade como prática moral, e não como simples formalidade religiosa.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XI, questão 886.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Como a obra relaciona humildade e conhecimento?","option_a":"O conhecimento exige desprezo pelos demais.","option_b":"A humildade impede a investigação.","option_c":"A pessoa instruída não precisa rever suas opiniões.","option_d":"A humildade permite reconhecer limites e continuar aprendendo, sem transformar conhecimento em orgulho.","option_e":"O conhecimento torna alguém moralmente perfeito.","correct_option":"D","explanation":"A humildade favorece o aprendizado contínuo e evita que o saber seja convertido em vaidade ou presunção.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. XII, questões 785 e 919.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"O que a obra aponta como finalidade da lei de reprodução?","option_a":"A conservação e a continuidade da vida, dentro das leis naturais.","option_b":"A imposição de um único modelo familiar a todos.","option_c":"A eliminação da liberdade individual.","option_d":"A criação de privilégios entre grupos humanos.","option_e":"A interrupção do progresso dos Espíritos.","correct_option":"A","explanation":"O capítulo trata da reprodução como lei natural relacionada à continuidade das espécies e à vida social.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. IV, questões 686–701.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é a abordagem da obra sobre a pena de morte?","option_a":"É necessária em qualquer sociedade.","option_b":"É um instrumento de progresso moral.","option_c":"É sempre um dever religioso.","option_d":"É uma prática que deve ser abolida à medida que a sociedade progride moralmente.","option_e":"É indiferente à evolução social.","correct_option":"D","explanation":"A obra considera a pena de morte sinal de atraso moral e relaciona sua abolição ao progresso da humanidade.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. VI, questões 760–765.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Por que a riqueza pode representar uma prova moral?","option_a":"Porque torna inevitável a corrupção.","option_b":"Porque oferece oportunidades de usar recursos com responsabilidade ou ceder ao egoísmo e ao apego.","option_c":"Porque é sempre sinal de mérito espiritual.","option_d":"Porque impede qualquer prática de caridade.","option_e":"Porque elimina as dificuldades de escolha.","correct_option":"B","explanation":"A obra trata riqueza e pobreza como condições que podem testar o uso dos recursos e a conduta moral.","reference":"O Livro dos Espíritos, Livro Terceiro, cap. IX, questões 814–816.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"Qual é o sentido da progressão dos Espíritos?","option_a":"Uma transformação instantânea imposta de fora.","option_b":"Uma mudança apenas de aparência.","option_c":"Um desenvolvimento gradual, sem retrocesso definitivo na conquista já realizada.","option_d":"Uma hierarquia baseada em riqueza material.","option_e":"Uma evolução que dispensa esforço pessoal.","correct_option":"C","explanation":"A obra apresenta o progresso espiritual como gradual e orientado à perfeição, sem perda definitiva do avanço conquistado.","reference":"O Livro dos Espíritos, Livro Segundo, cap. I, questões 114–118.","difficulty":"medio","active":true},{"book":"livro_espiritos","statement":"O que a obra entende por emancipação da alma durante o sono?","option_a":"A libertação temporária e parcial dos laços que prendem o Espírito ao corpo.","option_b":"A morte definitiva do corpo.","option_c":"A perda de toda consciência.","option_d":"A transformação do sonho em lembrança perfeita.","option_e":"A suspensão completa do livre-arbítrio.","correct_option":"A","explanation":"O capítulo sobre emancipação da alma aborda o sono como condição em que o Espírito pode se desprender parcialmente dos vínculos corporais.","reference":"O Livro dos Espíritos, Livro Segundo, cap. VIII, questões 400–418.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Por que Kardec afirma que uma revelação doutrinária não deve depender de um único médium?","option_a":"Porque os médiuns não podem transmitir qualquer ensinamento.","option_b":"Porque uma fonte isolada não oferece a mesma garantia que a concordância independente de comunicações diversas.","option_c":"Porque somente textos impressos são válidos.","option_d":"Porque a experiência individual deve ser ignorada.","option_e":"Porque todos os médiuns precisam pertencer ao mesmo grupo.","correct_option":"B","explanation":"A introdução argumenta que a concordância espontânea em diferentes lugares reduz o risco de erro individual ou influência local.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção II.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Qual é a diferença entre fé cega e fé raciocinada, conforme a obra?","option_a":"A fé raciocinada rejeita toda espiritualidade.","option_b":"A fé cega é sempre baseada em estudo.","option_c":"A fé raciocinada pode enfrentar a razão e a investigação sem temer suas conclusões.","option_d":"A fé raciocinada dispensa reflexão.","option_e":"As duas são definidas como obediência sem exame.","correct_option":"C","explanation":"A obra valoriza uma fé que pode ser examinada e compreendida, em vez de depender de aceitação sem reflexão.","reference":"O Evangelho Segundo o Espiritismo, cap. XIX, itens 6–7.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Como o capítulo V explica a relação entre causas atuais e anteriores das aflições?","option_a":"Toda aflição é necessariamente castigo por um ato específico.","option_b":"As dificuldades podem ter causas na existência presente ou em experiências anteriores, sem que se deva julgar o sofrimento alheio.","option_c":"O sofrimento não tem qualquer relação com a vida moral.","option_d":"As causas anteriores anulam a responsabilidade presente.","option_e":"Toda dor deve ser aceita sem auxílio.","correct_option":"B","explanation":"O capítulo aborda diferentes origens possíveis das aflições e recomenda confiança, resignação e solidariedade.","reference":"O Evangelho Segundo o Espiritismo, cap. V, itens 4–10.","difficulty":"medio","active":true},{"book":"evangelho","statement":"O que caracteriza a resignação ensinada no capítulo V?","option_a":"Passividade diante de toda injustiça.","option_b":"Desistência de buscar alívio para o sofrimento.","option_c":"Aceitação lúcida das provas inevitáveis, sem revolta, mantendo o esforço para agir corretamente.","option_d":"Indiferença em relação à dor dos outros.","option_e":"A crença de que nada pode ser transformado.","correct_option":"C","explanation":"A resignação não significa omissão: é enfrentar as provas com confiança e serenidade, sem abandonar o dever de agir.","reference":"O Evangelho Segundo o Espiritismo, cap. V, itens 12–13.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Qual é a finalidade das instruções espirituais acrescentadas aos capítulos?","option_a":"Substituir o texto dos Evangelhos por opiniões pessoais.","option_b":"Oferecer comentários sem relação com o tema.","option_c":"Provar a superioridade de um médium.","option_d":"Complementar os preceitos com ensinamentos atribuídos a diferentes Espíritos e médiuns.","option_e":"Estabelecer uma hierarquia de médiuns.","correct_option":"D","explanation":"Kardec explica que as instruções foram escolhidas de diversas origens para desenvolver e aplicar os preceitos morais.","reference":"O Evangelho Segundo o Espiritismo, Introdução, seção I.","difficulty":"medio","active":true},{"book":"evangelho","statement":"No capítulo VII, por que a humildade é apresentada como condição para o progresso espiritual?","option_a":"Porque permite reconhecer as próprias imperfeições e acolher o aprendizado.","option_b":"Porque exige abandonar toda opinião própria.","option_c":"Porque impede a busca do conhecimento.","option_d":"Porque garante superioridade sobre os outros.","option_e":"Porque elimina a necessidade de esforço.","correct_option":"A","explanation":"A humildade abre espaço para o reconhecimento das próprias limitações e para a transformação moral.","reference":"O Evangelho Segundo o Espiritismo, cap. VII, itens 1–2.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Como o capítulo X recomenda lidar com os erros alheios?","option_a":"Divulgá-los para servir de exemplo.","option_b":"Aplicar indulgência e examinar primeiro as próprias imperfeições.","option_c":"Ignorá-los mesmo quando é preciso proteger alguém.","option_d":"Condenar a pessoa sem considerar as circunstâncias.","option_e":"Exigir reparação pública em todos os casos.","correct_option":"B","explanation":"O capítulo ensina a indulgência, sem confundir compreensão com aprovação do erro ou omissão diante do mal.","reference":"O Evangelho Segundo o Espiritismo, cap. X, itens 11–13.","difficulty":"medio","active":true},{"book":"evangelho","statement":"O que significa a recomendação de reconciliar-se com o adversário enquanto se está a caminho?","option_a":"Evitar qualquer diálogo sobre conflitos.","option_b":"Esperar que o outro tome sempre a iniciativa.","option_c":"Buscar resolver desentendimentos e reparar ofensas antes que se agravem.","option_d":"Renunciar à justiça em qualquer circunstância.","option_e":"Manter ressentimento até obter vantagem.","correct_option":"C","explanation":"O ensinamento recomenda a reconciliação e a solução responsável dos conflitos antes que produzam consequências maiores.","reference":"O Evangelho Segundo o Espiritismo, cap. X, item 5.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Por que o capítulo XIII critica a ostentação na prática da caridade?","option_a":"Porque toda ajuda material é inadequada.","option_b":"Porque a caridade só deve ser feita em segredo absoluto.","option_c":"Porque a publicidade torna a doação automaticamente inútil.","option_d":"Porque a busca de reconhecimento pode transformar o bem em vaidade e interesse pessoal.","option_e":"Porque o auxílio deve ser limitado aos conhecidos.","correct_option":"D","explanation":"A obra destaca a intenção desinteressada e critica a exibição que procura aplauso ou prestígio.","reference":"O Evangelho Segundo o Espiritismo, cap. XIII, itens 1–3.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Como o capítulo XIV interpreta os vínculos familiares que ultrapassam o parentesco corporal?","option_a":"Como relações que podem ter origem em afinidades e compromissos espirituais.","option_b":"Como laços sem qualquer importância moral.","option_c":"Como prova de que todos os familiares pensam igual.","option_d":"Como vínculos que impedem a reencarnação.","option_e":"Como relações exclusivamente econômicas.","correct_option":"A","explanation":"O capítulo distingue família corporal e família espiritual, ressaltando afinidades e deveres que podem atravessar existências.","reference":"O Evangelho Segundo o Espiritismo, cap. XIV, itens 8–9.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Qual é o risco moral apontado no capítulo XVI em relação à riqueza?","option_a":"A riqueza sempre impede o desenvolvimento moral.","option_b":"O apego aos bens pode dominar a pessoa e afastá-la dos valores espirituais.","option_c":"A riqueza torna impossível praticar a caridade.","option_d":"A pobreza é garantia automática de virtude.","option_e":"O uso responsável dos recursos é condenado.","correct_option":"B","explanation":"O capítulo alerta para o apego e para a transformação da riqueza em finalidade suprema, em vez de instrumento de bem.","reference":"O Evangelho Segundo o Espiritismo, cap. XVI, itens 7–9.","difficulty":"medio","active":true},{"book":"evangelho","statement":"No capítulo XVII, como se reconhece a verdadeira caridade?","option_a":"Pela quantidade de pessoas que aplaudem.","option_b":"Pela fama pública de quem a pratica.","option_c":"Pela coerência entre sentimento, intenção e ação em favor do próximo.","option_d":"Pela posição social do benfeitor.","option_e":"Pelo valor material isolado da doação.","correct_option":"C","explanation":"A perfeição moral é relacionada à vivência concreta das virtudes, e não à aparência ou ao reconhecimento público.","reference":"O Evangelho Segundo o Espiritismo, cap. XVII, itens 1–3.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Qual é a lição moral da parábola do semeador, abordada no capítulo XVIII?","option_a":"Todos recebem o ensinamento e o aproveitam da mesma maneira.","option_b":"O conhecimento não exige esforço pessoal.","option_c":"A mensagem só produz frutos por imposição externa.","option_d":"A receptividade e a perseverança influenciam os frutos que o ensinamento produz.","option_e":"A dificuldade de compreensão é sempre definitiva.","correct_option":"D","explanation":"A parábola é usada para refletir sobre diferentes disposições diante do ensinamento e a necessidade de perseverança.","reference":"O Evangelho Segundo o Espiritismo, cap. XVIII, item 1.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Como o capítulo XX interpreta a expressão “trabalhadores da última hora”?","option_a":"Como convite ao trabalho moral, mesmo para quem começa mais tarde.","option_b":"Como justificativa para não agir enquanto jovem.","option_c":"Como privilégio reservado a um grupo.","option_d":"Como condenação de quem começou cedo.","option_e":"Como referência exclusiva a trabalho remunerado.","correct_option":"A","explanation":"A parábola valoriza a disposição sincera para o trabalho no bem, independentemente do momento em que a pessoa começa.","reference":"O Evangelho Segundo o Espiritismo, cap. XX, itens 1–3.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Por que o capítulo XXI recomenda avaliar os frutos de um ensinamento?","option_a":"Porque a eloquência basta para provar a verdade.","option_b":"Porque títulos e reputação são garantias absolutas.","option_c":"Porque a coerência entre discurso e conduta revela o valor moral do ensinamento.","option_d":"Porque a popularidade substitui o discernimento.","option_e":"Porque a aparência física indica elevação espiritual.","correct_option":"C","explanation":"A obra orienta a julgar os ensinamentos pelos efeitos e pela conduta de quem os transmite.","reference":"O Evangelho Segundo o Espiritismo, cap. XXI, itens 1–3.","difficulty":"medio","active":true},{"book":"evangelho","statement":"No capítulo XXV, o que significa “buscai e achareis” na interpretação moral da obra?","option_a":"Esperar resultados sem esforço.","option_b":"Empenhar-se, estudar e agir, confiando que o esforço sincero encontra caminhos.","option_c":"Exigir que a vida atenda a todos os desejos.","option_d":"Buscar apenas bens materiais.","option_e":"Desistir diante do primeiro obstáculo.","correct_option":"B","explanation":"O capítulo relaciona a busca ao esforço e à iniciativa, não à espera passiva de resultados.","reference":"O Evangelho Segundo o Espiritismo, cap. XXV, itens 1–5.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Qual é o princípio do capítulo XXVI sobre dar de graça o que de graça se recebe?","option_a":"O conhecimento espiritual deve ser vendido pelo preço mais alto.","option_b":"A caridade depende de pagamento prévio.","option_c":"Os dons e conhecimentos recebidos gratuitamente não devem ser explorados para ganho indevido.","option_d":"Somente instituições podem ensinar moral.","option_e":"Toda atividade profissional é condenada.","correct_option":"C","explanation":"O capítulo aplica o princípio da gratuidade à prática mediúnica e ao uso dos dons recebidos, combatendo sua exploração comercial.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVI, itens 1–2.","difficulty":"medio","active":true},{"book":"evangelho","statement":"O que o capítulo XXVII ensina sobre a eficácia da prece?","option_a":"A prece obriga Deus a alterar suas leis.","option_b":"A prece elimina a necessidade de esforço.","option_c":"A prece garante qualquer pedido material.","option_d":"A prece pode fortalecer, esclarecer e favorecer a sintonia moral, sem funcionar como imposição à vontade divina.","option_e":"A prece substitui a responsabilidade pessoal.","correct_option":"D","explanation":"A obra apresenta a prece como recurso de elevação e auxílio, sem tratá-la como mecanismo para exigir favores.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVII, itens 1–4.","difficulty":"medio","active":true},{"book":"evangelho","statement":"Por que a obra valoriza a oração espontânea e compreendida?","option_a":"Porque a sinceridade e a consciência do que se expressa são mais importantes que a repetição mecânica.","option_b":"Porque toda oração tradicional é proibida.","option_c":"Porque a oração deve ser longa para ter valor.","option_d":"Porque a forma externa garante o resultado.","option_e":"Porque a oração dispensa a transformação moral.","correct_option":"A","explanation":"O capítulo sobre a prece valoriza o sentimento, a intenção e a compreensão, em vez da repetição vazia.","reference":"O Evangelho Segundo o Espiritismo, cap. XXVII, itens 1–4.","difficulty":"medio","active":true}]$questions$::jsonb)
  AS x(book text, statement text, option_a text, option_b text, option_c text, option_d text, option_e text, correct_option text, explanation text, reference text, difficulty text, active boolean)
)
INSERT INTO public.questions (book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active)
SELECT book, statement, option_a, option_b, option_c, option_d, option_e, correct_option, explanation, reference, difficulty, active FROM incoming
ON CONFLICT (statement) DO NOTHING;
